template <class P>
void print_tlwe_ab(const TFHEpp::TLWE<P> &c, const std::string &name = "")
{
    if (!name.empty()) std::cout << name << ":\n";
    std::cout << "a = [";
    for (int i = 0; i < P::k * P::n; i++)
    {
        std::cout << c[i];
        if (i < P::k * P::n - 1) std::cout << ", ";
    }
    std::cout << "]\n";
    std::cout << "b = " << c[P::k * P::n] << "\n";
}

template<typename P>
void print_tlwe_key(const TFHESecretKey &sk, const std::string &name) {
    auto key_arr = sk.key.get<P>();
    std::cout << name << " size: " << key_arr.size() << "\n";
    for (size_t i = 0; i < key_arr.size(); i++) {
        std::cout << (int)key_arr[i] << " ";
    }
    std::cout << "\n";
}

void print_secret_key(const TFHESecretKey &sk) {
    std::cout << "=== Secret Key ===\n";
    print_tlwe_key<Lvl0>(sk, "Lvl0 TLWE key");
    print_tlwe_key<Lvl1>(sk, "Lvl1 TLWE key");
    print_tlwe_key<Lvl2>(sk, "Lvl2 TLWE key");
}

void multithread_my_comparation_test(uint32_t plain_bits, int num_test, int thread_num = std::thread::hardware_concurrency()) {
    std::cout << "------ Test of " << plain_bits << " bits comparation (multithread) ------" << std::endl;
    std::cout << "Test Time : " << num_test << " Thread num: " << thread_num << std::endl;
    std::cout << "Plain bits : " << plain_bits << std::endl;

    using P = Lvl1;
    TFHESecretKey sk;
    TFHEEvalKey ek;
    ek.emplacebkfft<Lvl01>(sk);
    ek.emplaceiksk<Lvl10>(sk);
    sk.key.lvl0[0]=1;
    sk.key.lvl0[1]=1;
    uint32_t scale_bits = std::numeric_limits<P::T>::digits - plain_bits - 1;
    std::cout << "scale_bits : " << scale_bits << std::endl;

    std::vector<uint32_t> error_time(2, 0);
    std::mutex mtx;

    auto worker = [&](int start_idx, int end_idx) {
        std::random_device seed_gen;
        std::default_random_engine engine(seed_gen());

        std::uniform_int_distribution<typename P::T> message(0, (1 << (plain_bits - 1)) - 1);
        std::uniform_int_distribution<typename P::T> type(0, 1);

        for (int test = start_idx; test < end_idx; test++) {
            typename P::T p1 = message(engine);
            // typename P::T p2 = message(engine);
            typename P::T p2 = p1;

            int ans = (p2 >= p1) ? 1 : 0;

            bool result_type = ARITHMETIC;   //原本为ARITHMETIC
            // bool result_type = LOGIC;

            TFHEpp::TLWE<P> c1 = TFHEpp::tlweSymInt32Encrypt<P>(p1, P::α, pow(2., scale_bits), sk.key.get<P>());
            TFHEpp::TLWE<P> c2 = TFHEpp::tlweSymInt32Encrypt<P>(p2, P::α, pow(2., scale_bits), sk.key.get<P>());

            TLWELvl1 c_ans;

            // 原始比较方案
            // greater_than_equal<Lvl1>(c2, c1, c_ans, plain_bits, ek, ARITHMETIC);
            // int o_ans = TFHEpp::tlweSymInt32Decrypt<Lvl1>(c_ans, pow(2., 28), sk.key.get<Lvl1>());
            // if (o_ans != ans) {
            //     std::lock_guard<std::mutex> lock(mtx);
            //     error_time[0]++;
            //     std::cout << "\n========== ERROR DETECTED ori ==========\n";
            //     std::cout << "Test index: " << test << "\n";
            //     std::cout << "Expected ans: " << ans << " | Decrypted ori_ans: " << o_ans << "\n";
            //     std::cout << "Plain inputs: p1=" << p1 << " p2=" << p2 << "\n";
            //     std::cout << "------------------------------------\n";
            //     std::cout << "[Decrypt c1] p1 (encrypted):\n";
            //     TFHEpp::tlweSymInt32Decrypt_print<Lvl1>(c1, pow(2., scale_bits), sk.key.get<Lvl1>());
            //     std::cout << "[Decrypt c2] p2 (encrypted):\n";
            //     TFHEpp::tlweSymInt32Decrypt_print<Lvl1>(c2, pow(2., scale_bits), sk.key.get<Lvl1>());
            //     std::cout << "[Decrypt final c_ans]:\n";
            //     TFHEpp::tlweSymInt32Decrypt_print<Lvl1>(c_ans, pow(2., 28), sk.key.get<Lvl1>());
            //     std::cout << "====================================\n";
            // }

            // 改进比较
            my_greater_than_equal<Lvl1>(c2, c1, c_ans, plain_bits, ek, result_type, 28);

            int d_ans = TFHEpp::tlweSymInt32Decrypt<Lvl1>(c_ans, pow(2., 28), sk.key.get<Lvl1>());

            if (d_ans != ans) {
                std::lock_guard<std::mutex> lock(mtx);
                error_time[1]++;

                std::cout << "\n========== ERROR DETECTED ==========\n";
                std::cout << "Expected ans: " << ans << " | Decrypted ans: " << d_ans << "\n";
                std::cout << "Plain inputs: p1=" << p1 << " p2=" << p2 << "\n";
                std::cout << "------------------------------------\n";
                std::cout << "[Encrypt c1]:\n";
                print_tlwe_ab<P>(c1, "c1");
                std::cout << "[Encrypt c2]:\n";
                print_tlwe_ab<P>(c2, "c2");
                print_secret_key(sk);

                std::cout << "[Decrypt c1] p1 (encrypted):\n";
                TFHEpp::tlweSymInt32Decrypt_print<Lvl1>(c1, pow(2., scale_bits), sk.key.get<Lvl1>());
                std::cout << "[Decrypt c2] p2 (encrypted):\n";
                TFHEpp::tlweSymInt32Decrypt_print<Lvl1>(c2, pow(2., scale_bits), sk.key.get<Lvl1>());

                std::cout << "[Decrypt final c_ans]:\n";
                TFHEpp::tlweSymInt32Decrypt_print<Lvl1>(c_ans, pow(2., 28), sk.key.get<Lvl1>());

                std::cout << "====================================\n";
            }
        }

    };

    std::vector<std::thread> threads;
    int block_size = num_test / thread_num;
    int remain = num_test % thread_num;
    int start_idx = 0;

    for (int i = 0; i < thread_num; i++) {
        int end_idx = start_idx + block_size + (i < remain ? 1 : 0);
        threads.emplace_back(worker, start_idx, end_idx);
        start_idx = end_idx;
    }

    for (auto &t : threads) {
        t.join();
    }

    // std::cout << "ori error time :" << error_time[0] << std::endl;
    std::cout << "my_greater_than_equal error time :" << error_time[1] << std::endl;
}


